// src/App.js
import React, { useState, useEffect } from 'react';
import './App.css';

const API_BASE = 'http://localhost:5000/api/user';

function App() {
  // User state
  const [currentUser, setCurrentUser] = useState(null);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [matches, setMatches] = useState([]);
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [activeTab, setActiveTab] = useState('discover');
  const [isLoading, setIsLoading] = useState(false);
  const [showProfile, setShowProfile] = useState(false);
  const [showMatchDetails, setShowMatchDetails] = useState(false);
  const [selectedMatch, setSelectedMatch] = useState(null);
  const [registrationStep, setRegistrationStep] = useState(1);
  const [registrationData, setRegistrationData] = useState({
    phone: '',
    name: '',
    age: '',
    gender: 'Male',
    county: '',
    town: '',
    education: '',
    profession: '',
    maritalStatus: 'Single',
    religion: '',
    ethnicity: '',
    description: ''
  });
  const [notifications, setNotifications] = useState([]);
  const [incomingRequests, setIncomingRequests] = useState([]);
  const [interests, setInterests] = useState([]);

  // Load user session
  useEffect(() => {
    const savedUser = localStorage.getItem('penzi_user');
    if (savedUser) {
      const user = JSON.parse(savedUser);
      setCurrentUser(user);
      setIsLoggedIn(true);
      loadMatches(user.phone);
      loadIncomingRequests(user.phone);
      loadInterests(user.phone);
    }
  }, []);

  // Save user session
  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('penzi_user', JSON.stringify(currentUser));
    }
  }, [currentUser]);

  // Load matches for user
  const loadMatches = async (phone) => {
    try {
      const response = await fetch(`${API_BASE}/${phone}/matches?age_range=20-40&town=Nairobi`);
      const data = await response.json();
      if (data.matches) {
        setMatches(data.matches);
      }
    } catch (error) {
      console.error('Error loading matches:', error);
    }
  };

  // Load incoming requests
  const loadIncomingRequests = async (phone) => {
    try {
      const response = await fetch(`${API_BASE}/${phone}/incoming-requests`);
      const data = await response.json();
      if (data.requests) {
        setIncomingRequests(data.requests);
      }
    } catch (error) {
      console.error('Error loading requests:', error);
    }
  };

  // Load interests
  const loadInterests = async (phone) => {
    try {
      const response = await fetch(`${API_BASE}/${phone}/my-interests`);
      const data = await response.json();
      if (data.interests) {
        setInterests(data.interests);
      }
    } catch (error) {
      console.error('Error loading interests:', error);
    }
  };

  // Handle registration
  const handleRegistration = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      // Step 1: Register user
      const registerResponse = await fetch(`${API_BASE}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          phone_number: registrationData.phone,
          name: registrationData.name,
          age: registrationData.age,
          gender: registrationData.gender,
          county: registrationData.county,
          town: registrationData.town
        })
      });

      const registerData = await registerResponse.json();

      if (registerData.success) {
        // Step 2: Complete profile
        const profileResponse = await fetch(`${API_BASE}/${registrationData.phone}/complete-profile`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            education_level: registrationData.education,
            profession: registrationData.profession,
            marital_status: registrationData.maritalStatus,
            religion: registrationData.religion,
            ethnicity: registrationData.ethnicity
          })
        });

        // Step 3: Add self-description
        if (registrationData.description) {
          await fetch(`${API_BASE}/${registrationData.phone}/self-description`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              description: registrationData.description
            })
          });
        }

        // Login user
        const user = {
          phone: registrationData.phone,
          name: registrationData.name,
          age: registrationData.age,
          gender: registrationData.gender,
          county: registrationData.county,
          town: registrationData.town
        };

        setCurrentUser(user);
        setIsLoggedIn(true);
        localStorage.setItem('penzi_user', JSON.stringify(user));

        // Load matches
        await loadMatches(user.phone);
        await loadIncomingRequests(user.phone);
        await loadInterests(user.phone);

        addNotification('🎉 Welcome to PENZI! Start finding your perfect match today.');
      } else {
        addNotification('❌ Registration failed. Please try again.', 'error');
      }
    } catch (error) {
      console.error('Registration error:', error);
      addNotification('❌ Connection error. Please check your network.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  // Handle expressing interest
  const expressInterest = async (targetPhone) => {
    setIsLoading(true);
    try {
      const response = await fetch(`${API_BASE}/${currentUser.phone}/send-interest`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          target_phone: targetPhone
        })
      });

      const data = await response.json();
      if (data.success) {
        addNotification('💕 Interest sent! They will be notified.');
        // Remove from matches or mark as interested
        setMatches(matches.filter(m => m.phone !== targetPhone));
        await loadInterests(currentUser.phone);
      } else {
        addNotification('❌ Could not send interest. Please try again.', 'error');
      }
    } catch (error) {
      console.error('Error expressing interest:', error);
      addNotification('❌ Connection error. Please try again.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  // Handle responding to request
  const respondToRequest = async (targetPhone, action) => {
    setIsLoading(true);
    try {
      const response = await fetch(`${API_BASE}/${currentUser.phone}/respond-to-request`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          user_phone: targetPhone,
          action: action
        })
      });

      const data = await response.json();
      if (data.success) {
        if (action === 'accept') {
          addNotification('✅ You accepted the request! Start chatting with your match.');
          // Move to connections
        } else {
          addNotification('❌ You declined the request.');
        }
        await loadIncomingRequests(currentUser.phone);
      }
    } catch (error) {
      console.error('Error responding to request:', error);
      addNotification('❌ Connection error. Please try again.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  // Add notification
  const addNotification = (message, type = 'success') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  // Render registration form
  const renderRegistration = () => {
    const steps = [
      {
        title: '📱 Create Your Account',
        subtitle: 'Start your dating journey',
        icon: '💑',
        fields: [
          { key: 'phone', label: 'Phone Number', placeholder: '0712345678', type: 'tel' },
          { key: 'name', label: 'Full Name', placeholder: 'John Doe' },
          { key: 'age', label: 'Age', placeholder: '25', type: 'number' },
          { key: 'gender', label: 'Gender', type: 'select', options: ['Male', 'Female', 'Other'] },
          { key: 'county', label: 'County', placeholder: 'Nairobi' },
          { key: 'town', label: 'Town/City', placeholder: 'Westlands' }
        ]
      },
      {
        title: '📝 Tell Us About Yourself',
        subtitle: 'Help us find your perfect match',
        icon: '📋',
        fields: [
          { key: 'education', label: 'Education Level', type: 'select', options: ['Primary', 'Secondary', 'Certificate', 'Diploma', 'Graduate', 'Post Graduate'] },
          { key: 'profession', label: 'Profession', placeholder: 'Engineer' },
          { key: 'maritalStatus', label: 'Marital Status', type: 'select', options: ['Single', 'Married', 'Divorced', 'Widowed', 'Separated'] },
          { key: 'religion', label: 'Religion', placeholder: 'Christian' },
          { key: 'ethnicity', label: 'Ethnicity/Tribe', placeholder: 'Kikuyu' }
        ]
      },
      {
        title: '💭 Describe Yourself',
        subtitle: 'What makes you special?',
        icon: '💫',
        fields: [
          { key: 'description', label: 'Tell us about yourself', placeholder: 'I am kind, adventurous, love traveling and meeting new people...', type: 'textarea' }
        ]
      }
    ];

    const currentStep = steps[registrationStep - 1];

    return (
      <div className="registration-container">
        <div className="registration-card">
          <div className="registration-header">
            <div className="registration-icon">💑</div>
            <h1>PENZI Dating</h1>
            <p>Find love through SMS - Simple, Safe, Secure</p>
          </div>

          <div className="registration-progress">
            {steps.map((step, index) => (
              <div key={index} className={`progress-step ${index + 1 <= registrationStep ? 'active' : ''}`}>
                <div className="progress-circle">{index + 1}</div>
                <div className="progress-label">{step.title.split(' ')[1]}</div>
              </div>
            ))}
          </div>

          <form onSubmit={handleRegistration} className="registration-form">
            <div className="step-header">
              <h2>{currentStep.title}</h2>
              <p>{currentStep.subtitle}</p>
            </div>

            {currentStep.fields.map((field) => (
              <div key={field.key} className="form-group">
                <label>{field.label}</label>
                {field.type === 'select' ? (
                  <select
                    value={registrationData[field.key] || ''}
                    onChange={(e) => setRegistrationData({ ...registrationData, [field.key]: e.target.value })}
                    required
                  >
                    <option value="">Select {field.label}</option>
                    {field.options.map(opt => (
                      <option key={opt} value={opt}>{opt}</option>
                    ))}
                  </select>
                ) : field.type === 'textarea' ? (
                  <textarea
                    value={registrationData[field.key] || ''}
                    onChange={(e) => setRegistrationData({ ...registrationData, [field.key]: e.target.value })}
                    placeholder={field.placeholder}
                    rows={4}
                    required={field.key !== 'description'}
                  />
                ) : (
                  <input
                    type={field.type || 'text'}
                    value={registrationData[field.key] || ''}
                    onChange={(e) => setRegistrationData({ ...registrationData, [field.key]: e.target.value })}
                    placeholder={field.placeholder}
                    required
                  />
                )}
              </div>
            ))}

            <div className="registration-actions">
              {registrationStep > 1 && (
                <button
                  type="button"
                  onClick={() => setRegistrationStep(registrationStep - 1)}
                  className="btn-secondary"
                >
                  Back
                </button>
              )}
              {registrationStep < steps.length ? (
                <button
                  type="button"
                  onClick={() => setRegistrationStep(registrationStep + 1)}
                  className="btn-primary"
                >
                  Next Step →
                </button>
              ) : (
                <button
                  type="submit"
                  disabled={isLoading}
                  className="btn-primary"
                >
                  {isLoading ? 'Creating Account...' : '💑 Find Your Match'}
                </button>
              )}
            </div>

            <div className="registration-footer">
              <p>By signing up, you agree to our Terms & Conditions</p>
              <p className="security-note">🔒 Your data is safe and private</p>
            </div>
          </form>
        </div>
      </div>
    );
  };

  // Render main app
  const renderMainApp = () => {
    return (
      <div className="app-container">
        {/* Header */}
        <header className="app-header">
          <div className="header-left">
            <h1>💑 PENZI</h1>
            <span className="header-badge">❤️ Live</span>
          </div>
          <div className="header-right">
            <span className="user-greeting">👋 {currentUser?.name}</span>
            <button 
              className="profile-btn"
              onClick={() => setShowProfile(!showProfile)}
            >
              👤
            </button>
          </div>
        </header>

        {/* Navigation Tabs */}
        <nav className="app-nav">
          <button 
            className={`nav-item ${activeTab === 'discover' ? 'active' : ''}`}
            onClick={() => setActiveTab('discover')}
          >
            🔍 Discover
          </button>
          <button 
            className={`nav-item ${activeTab === 'matches' ? 'active' : ''}`}
            onClick={() => setActiveTab('matches')}
          >
            💕 Matches
          </button>
          <button 
            className={`nav-item ${activeTab === 'requests' ? 'active' : ''}`}
            onClick={() => setActiveTab('requests')}
          >
            📬 Requests
            {incomingRequests.length > 0 && (
              <span className="badge">{incomingRequests.length}</span>
            )}
          </button>
          <button 
            className={`nav-item ${activeTab === 'chat' ? 'active' : ''}`}
            onClick={() => setActiveTab('chat')}
          >
            💬 Chat
          </button>
        </nav>

        {/* Notifications */}
        <div className="notifications">
          {notifications.map(notif => (
            <div key={notif.id} className={`notification ${notif.type || 'success'}`}>
              {notif.message}
            </div>
          ))}
        </div>

        {/* Main Content */}
        <main className="main-content">
          {activeTab === 'discover' && renderDiscover()}
          {activeTab === 'matches' && renderMatches()}
          {activeTab === 'requests' && renderRequests()}
          {activeTab === 'chat' && renderChat()}
        </main>

        {/* Profile Modal */}
        {showProfile && renderProfileModal()}

        {/* Match Details Modal */}
        {showMatchDetails && renderMatchDetails()}
      </div>
    );
  };

  // Render Discover tab
  const renderDiscover = () => {
    if (matches.length === 0) {
      return (
        <div className="empty-state">
          <div className="empty-icon">🔍</div>
          <h2>No Matches Found</h2>
          <p>Update your preferences to find more matches</p>
          <button className="btn-primary" onClick={() => loadMatches(currentUser.phone)}>
            Refresh Matches
          </button>
        </div>
      );
    }

    const currentMatch = matches[currentMatchIndex] || matches[0];

    return (
      <div className="discover-container">
        <div className="match-card">
          <div className="match-card-header">
            <div className="match-avatar">
              {currentMatch?.name?.charAt(0) || '?'}
            </div>
            <div className="match-info">
              <h3>{currentMatch?.name || 'Unknown'}</h3>
              <p>{currentMatch?.age || '?'} years • {currentMatch?.town || 'Unknown'}</p>
            </div>
          </div>

          <div className="match-details">
            <div className="detail-item">
              <span className="detail-label">💼 Profession</span>
              <span className="detail-value">{currentMatch?.profession || 'Not specified'}</span>
            </div>
            <div className="detail-item">
              <span className="detail-label">🎓 Education</span>
              <span className="detail-value">{currentMatch?.education || 'Not specified'}</span>
            </div>
            <div className="detail-item">
              <span className="detail-label">🙏 Religion</span>
              <span className="detail-value">{currentMatch?.religion || 'Not specified'}</span>
            </div>
            <div className="detail-item">
              <span className="detail-label">🌍 Ethnicity</span>
              <span className="detail-value">{currentMatch?.ethnicity || 'Not specified'}</span>
            </div>
            {currentMatch?.description && (
              <div className="detail-item full-width">
                <span className="detail-label">💭 About Me</span>
                <span className="detail-value description">{currentMatch.description}</span>
              </div>
            )}
          </div>

          <div className="match-actions">
            <button 
              className="btn-secondary"
              onClick={() => setShowMatchDetails(true)}
            >
              👤 View Full Profile
            </button>
            <button 
              className="btn-primary"
              onClick={() => expressInterest(currentMatch.phone)}
              disabled={isLoading}
            >
              💕 I'm Interested
            </button>
          </div>

          <div className="match-navigation">
            <button 
              className="nav-btn"
              onClick={() => setCurrentMatchIndex(Math.max(0, currentMatchIndex - 1))}
              disabled={currentMatchIndex === 0}
            >
              ⬅ Previous
            </button>
            <span className="match-counter">
              {currentMatchIndex + 1} of {matches.length}
            </span>
            <button 
              className="nav-btn"
              onClick={() => setCurrentMatchIndex(Math.min(matches.length - 1, currentMatchIndex + 1))}
              disabled={currentMatchIndex === matches.length - 1}
            >
              Next ➡
            </button>
          </div>
        </div>
      </div>
    );
  };

  // Render Matches tab
  const renderMatches = () => {
    const matchedUsers = interests.filter(i => i.status === 'accepted');

    if (matchedUsers.length === 0) {
      return (
        <div className="empty-state">
          <div className="empty-icon">💕</div>
          <h2>No Matches Yet</h2>
          <p>Start discovering and expressing interest to find your match</p>
          <button className="btn-primary" onClick={() => setActiveTab('discover')}>
            Discover People
          </button>
        </div>
      );
    }

    return (
      <div className="matches-grid">
        {matchedUsers.map((match, index) => (
          <div key={index} className="match-item">
            <div className="match-avatar">{match.name?.charAt(0) || '?'}</div>
            <div className="match-info">
              <h4>{match.name}</h4>
              <p>{match.age} years • {match.town}</p>
            </div>
            <button className="btn-chat">💬</button>
          </div>
        ))}
      </div>
    );
  };

  // Render Requests tab
  const renderRequests = () => {
    if (incomingRequests.length === 0) {
      return (
        <div className="empty-state">
          <div className="empty-icon">📬</div>
          <h2>No Requests</h2>
          <p>When someone shows interest, you'll see it here</p>
        </div>
      );
    }

    return (
      <div className="requests-list">
        {incomingRequests.map((request, index) => (
          <div key={index} className="request-item">
            <div className="request-info">
              <div className="request-avatar">{request.name?.charAt(0) || '?'}</div>
              <div>
                <h4>{request.name}</h4>
                <p>{request.age} years • {request.town}</p>
                <p className="request-message">💕 Shows interest in you</p>
              </div>
            </div>
            <div className="request-actions">
              <button 
                className="btn-accept"
                onClick={() => respondToRequest(request.phone, 'accept')}
              >
                ✅ Accept
              </button>
              <button 
                className="btn-decline"
                onClick={() => respondToRequest(request.phone, 'reject')}
              >
                ❌ Decline
              </button>
            </div>
          </div>
        ))}
      </div>
    );
  };

  // Render Chat tab
  const renderChat = () => {
    return (
      <div className="chat-container">
        <div className="chat-header">
          <h3>💬 Messages</h3>
        </div>
        <div className="chat-messages">
          {messages.length === 0 ? (
            <div className="empty-state">
              <div className="empty-icon">💬</div>
              <h3>No Messages</h3>
              <p>Start a conversation with your matches</p>
            </div>
          ) : (
            messages.map((msg, index) => (
              <div key={index} className={`message ${msg.sender === currentUser?.phone ? 'sent' : 'received'}`}>
                <p>{msg.text}</p>
                <span className="message-time">{msg.time}</span>
              </div>
            ))
          )}
        </div>
        <div className="chat-input">
          <input
            type="text"
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            placeholder="Type a message..."
            onKeyPress={(e) => {
              if (e.key === 'Enter' && newMessage.trim()) {
                setMessages([...messages, {
                  sender: currentUser?.phone,
                  text: newMessage,
                  time: new Date().toLocaleTimeString()
                }]);
                setNewMessage('');
              }
            }}
          />
          <button 
            className="btn-send"
            onClick={() => {
              if (newMessage.trim()) {
                setMessages([...messages, {
                  sender: currentUser?.phone,
                  text: newMessage,
                  time: new Date().toLocaleTimeString()
                }]);
                setNewMessage('');
              }
            }}
          >
            Send
          </button>
        </div>
      </div>
    );
  };

  // Render Profile Modal
  const renderProfileModal = () => {
    return (
      <div className="modal-overlay" onClick={() => setShowProfile(false)}>
        <div className="modal-content" onClick={(e) => e.stopPropagation()}>
          <button className="modal-close" onClick={() => setShowProfile(false)}>✕</button>
          <div className="profile-header">
            <div className="profile-avatar">{currentUser?.name?.charAt(0) || '?'}</div>
            <h2>{currentUser?.name}</h2>
            <p>{currentUser?.age} years • {currentUser?.town}</p>
          </div>
          <div className="profile-details">
            <div className="profile-item">
              <span className="label">📞 Phone</span>
              <span>{currentUser?.phone}</span>
            </div>
            <div className="profile-item">
              <span className="label">🎓 Education</span>
              <span>{currentUser?.education || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">💼 Profession</span>
              <span>{currentUser?.profession || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">💍 Marital Status</span>
              <span>{currentUser?.maritalStatus || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">🙏 Religion</span>
              <span>{currentUser?.religion || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">🌍 Ethnicity</span>
              <span>{currentUser?.ethnicity || 'Not specified'}</span>
            </div>
            <div className="profile-item full-width">
              <span className="label">💭 About Me</span>
              <span>{currentUser?.description || 'No description yet'}</span>
            </div>
          </div>
          <button className="btn-primary full-width" onClick={() => setShowProfile(false)}>
            Close Profile
          </button>
        </div>
      </div>
    );
  };

  // Render Match Details Modal
  const renderMatchDetails = () => {
    const match = matches[currentMatchIndex];
    if (!match) return null;

    return (
      <div className="modal-overlay" onClick={() => setShowMatchDetails(false)}>
        <div className="modal-content" onClick={(e) => e.stopPropagation()}>
          <button className="modal-close" onClick={() => setShowMatchDetails(false)}>✕</button>
          <div className="profile-header">
            <div className="profile-avatar">{match.name?.charAt(0) || '?'}</div>
            <h2>{match.name}</h2>
            <p>{match.age} years • {match.town}</p>
          </div>
          <div className="profile-details">
            <div className="profile-item">
              <span className="label">💼 Profession</span>
              <span>{match.profession || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">🎓 Education</span>
              <span>{match.education || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">💍 Marital Status</span>
              <span>{match.maritalStatus || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">🙏 Religion</span>
              <span>{match.religion || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">🌍 Ethnicity</span>
              <span>{match.ethnicity || 'Not specified'}</span>
            </div>
            {match.description && (
              <div className="profile-item full-width">
                <span className="label">💭 About Me</span>
                <span>{match.description}</span>
              </div>
            )}
          </div>
          <div className="modal-actions">
            <button 
              className="btn-secondary"
              onClick={() => setShowMatchDetails(false)}
            >
              Close
            </button>
            <button 
              className="btn-primary"
              onClick={() => {
                expressInterest(match.phone);
                setShowMatchDetails(false);
              }}
            >
              💕 Express Interest
            </button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="app">
      {isLoggedIn ? renderMainApp() : renderRegistration()}
    </div>
  );
}

export default App;
